import {challenge as C} from './shared.js';
export default [
C(4,2,'限制梯度范数而不改变方向',{
 goal:'实现向量梯度的全局 L2 范数裁剪。',signature:'clip_gradient(gradient, limit)',contract:'gradient 为有限数字列表，limit>0。返回新列表；若 L2 范数超过 limit，整向量同比例缩放，否则保持数值。空输入返回 []。',
 context:'梯度很大时，一次更新可能跨过合适区域。全局范数裁剪保留方向，只限制长度。逐元素截断会改变向量方向，两种方法并不相同。本题只处理有限值；遇到 NaN 应另外定位根因。',
 steps:['计算 norm=sqrt(sum(g*g))。','norm>limit 时用 scale=limit/norm；否则 scale=1。','返回每项 g*scale，保持输入不变。零向量不应发生除零。'],worked:['梯度 [3,4] 的范数是 5。','limit=2.5 时 scale=0.5。','返回 [1.5,2]；两个分量比例仍为 3:4。'],mistake:'把每个分量分别截到 [-limit,limit]，不是本题的全局范数裁剪。',transfer:'真实训练通常在累积完成、必要的反缩放之后裁剪；裁剪位置不同可能改变更新。',
 cases:[['clip_gradient([3,4],2.5)','[1.5,2]','统一缩放'],['clip_gradient([0,0],1)','[0,0]','零梯度'],['clip_gradient([-1,1],3)','[-1,1]','小梯度保持'],['clip_gradient([],1)','[]','空向量']],solution:'import math\ndef clip_gradient(gradient,limit):\n    norm=math.sqrt(sum(g*g for g in gradient))\n    scale=limit/norm if norm>limit else 1\n    return [g*scale for g in gradient]\n',quiz:['[3,4] 裁剪到范数 1 后是什么？',['[1,1]','[0.6,0.8]','[3,4]'],1,'原范数 5，整向量乘 1/5。']
}),
C(4,4,'按有效 token 合并微批梯度',{
 goal:'合并多个长度不同的微批，让结果等价于按 token 平均。',signature:'merge_gradients(chunks)',contract:'chunks 为 (平均梯度向量,有效token数) 列表；各向量维度相同、数量为非负整数。返回加权平均向量；总有效数量为零抛 ValueError。',
 context:'梯度累积能把多次小批次计算合成一次更新。但小批次有效 token 数不同，简单平均会给短批次过高权重。目标若按 token 平均，就要先恢复每块的梯度和，再除以总 token 数。',
 steps:['先求全部有效数量之和，拒绝零监督。','对每个参数维度累加该维梯度乘该块 token 数。','逐维除以总数量，零数量块不贡献。'],worked:['梯度 [2,4] 对应 1 个 token，[10,0] 对应 3 个。','梯度和为 [32,4]，总 token 数 4。','返回 [8,1]，不是两向量的简单平均 [6,2]。'],mistake:'平均的平均只有在各块分母相同时才等价。',transfer:'DDP、累积步数和 loss reduction 会共同影响缩放；先从定义写出所需的全局目标。',cases:[['merge_gradients([([2,4],1),([10,0],3)])','[8,1]','不等长微批'],['merge_gradients([([99],0),([-2],4)])','[-2]','忽略零监督'],['merge_gradients([([3,5],2),([3,5],2)])','[3,5]','重复批次保持均值']],extraTests:[{name:'拒绝无监督更新',code:'try:\n    merge_gradients([([1],0)])\n    assert False\nexcept ValueError: pass'}],solution:'def merge_gradients(chunks):\n    total=sum(n for _,n in chunks)\n    if total==0: raise ValueError("no targets")\n    return [sum(g[i]*n for g,n in chunks if n)/total for i in range(len(chunks[0][0]))]\n',quiz:['把一个微批等分成两个相同均值的块，正确加权结果应怎样？',['改变一半','不变','翻倍'],1,'切块只是计算组织变化，不应改变同一 token 目标。']
}),
C(4,6,'计算评测中的分类错误',{
 goal:'输出混淆矩阵与准确率，区分不同错误类型。',signature:'classification_report(targets, predictions, classes)',contract:'两个列表等长非空，类别下标合法，classes≥1。返回 {"matrix":真实类为行、预测类为列的计数矩阵,"accuracy":正确比例}。',context:'只报告准确率可能掩盖某类样本全部失败。混淆矩阵保留错误去向：把物体 A 认成 B，与把所有物体都认成背景，对后续排错意味着不同问题。先写清行列含义，才不会把召回率与精确率混淆。',steps:['建立独立的 classes×classes 零矩阵。','每条记录在 matrix[target][prediction] 加一。','对角线计数之和除以样本数得到 accuracy。'],worked:['目标 [0,1,1]，预测 [0,0,1]。','矩阵 [[1,0],[1,1]]：有一个真实 1 被预测成 0。','准确率 2/3；仅有这个指标还不能判断所有子类都可靠。'],mistake:'交换行列不改变对角线准确率，却会改变错误解释。',transfer:'MMLU 等基准也依赖题目集合与评分规则；同名“accuracy”不能脱离协议比较。',cases:[['classification_report([0,1,1],[0,0,1],2)','{"matrix":[[1,0],[1,1]],"accuracy":0.6666666666666666}','定位错误方向'],['classification_report([1],[0],2)','{"matrix":[[0,0],[1,0]],"accuracy":0}','完全错误'],['classification_report([0,2],[0,2],3)','{"matrix":[[1,0,0],[0,0,0],[0,0,1]],"accuracy":1}','未出现类别保留行列']],solution:'def classification_report(targets,predictions,classes):\n    m=[[0]*classes for _ in range(classes)]\n    for y,p in zip(targets,predictions): m[y][p]+=1\n    return {"matrix":m,"accuracy":sum(m[i][i] for i in range(classes))/len(targets)}\n',quiz:['矩阵行是真实类、列是预测类，M[1][0]=5 表示？',['5 个真实 0 被预测为 1','5 个真实 1 被预测为 0','类别 1 有 5 个正确答案'],1,'先固定行列定义再解释数值。']
}),
C(4,7,'周项目：可复核的累积、裁剪与更新',{
 goal:'把加权梯度累积、全局裁剪和 SGD 更新串成一次正确更新。',signature:'optimizer_update(params, chunks, lr, limit)',contract:'params 与 chunks 中梯度向量维度一致，chunks 总有效数量>0，lr≥0，limit>0。先按 token 加权合并，再裁剪全局 L2 范数，最后返回新参数列表。',context:'局部功能都正确，组合顺序仍可能错误。先裁剪每块再合并，通常不等价于合并后裁剪。综合项目把“训练技巧”变成有明确顺序、输入和数值验收的更新程序。',steps:['按有效数量合并各维梯度。','计算合并向量的范数，一次性按 limit 缩放。','用旧参数减 lr*裁剪后梯度，返回新列表。'],worked:['params=[10,10]，合并梯度 [3,4]。','limit=2.5 时得到 [1.5,2]。','lr=0.1，输出 [9.85,9.8]。'],mistake:'对每块单独裁剪后再平均会改变目标方向；不要把示例中碰巧相等当成一般性质。',transfer:'这一条更新链是阅读实际 trainer 的检查模板；混合精度和分布式同步还需按框架验证位置。',cases:[['optimizer_update([10,10],[([3,4],2)],0.1,2.5)','[9.85,9.8]','先合并再裁剪'],['optimizer_update([1],[([2],1),([10],3)],0.1,100)','[0.2]','正确有效数量'],['optimizer_update([2,3],[([9,9],2)],0,1)','[2,3]','零学习率'],['optimizer_update([0],[([10],1),([-8],1)],1,2)','[-1]','不能逐块裁剪']],solution:'import math\ndef optimizer_update(params,chunks,lr,limit):\n    total=sum(n for _,n in chunks)\n    g=[sum(v[i]*n for v,n in chunks)/total for i in range(len(params))]\n    norm=math.sqrt(sum(x*x for x in g))\n    scale=limit/norm if norm>limit else 1\n    return [p-lr*x*scale for p,x in zip(params,g)]\n',quiz:['两块梯度分别为 10 和 -8，等权平均后裁剪到 2，最终梯度是？',['0','1','2'],1,'先平均得 1，范数没超过 2，无需裁剪。']
})];
